      commonMistakes: {
        id: 'common-mistakes',
        title: 'Common Mistakes',
        items: [
          '**Running n8n on a computer that sleeps.** Scheduled workflows do not run while it sleeps. Use an always-on host or change the power settings.',
          '**Loading a model that is too large.** If the model does not fit in free memory, replies can become very slow. Start with a 3B model and test larger ones before switching.',
          '**Exposing port 5678 directly to the internet.** Do not port-forward n8n. A tunnel also makes it reachable: use a strong owner password and two-factor authentication, require authentication on webhooks, restrict access to the editor and keep n8n updated.',
          '**Parsing free-form model output.** A model can wrap JSON in extra text. Use Ollama\'s JSON mode (`format: "json"`), say in the prompt which fields you need, and validate the result.',
          '**No failure alerts.** Add an n8n error workflow that notifies you through ntfy, Pushover or email.',
        ],
      },
