            type: 'tip',
            text: 'Liste de contrôle de configuration : ✅ OAuth Google Drive dans n8n ✅ Répertoire de sauvegarde local monté comme volume Docker ✅ Base de données SQLite initialisée avec une table `seen_files (hash TEXT PRIMARY KEY, path TEXT, ts TEXT)` ✅ Alerte d\'espace disque quand le volume de sauvegarde est >80 % plein ✅ Tunnel Cloudflare optionnel uniquement si vous voulez aussi un webhook de Drive au lieu du polling.',
