          'Instala Docker Desktop desde docker.com (un instalador; compatible con macOS, Linux, Windows).',
          'Instala Ollama desde ollama.com y descarga el modelo: `ollama pull llama3.2:3b` (descarga ~2 GB).',
          'Crea un directorio de trabajo (p. ej., `~/n8n-stack`) y agrega un archivo `docker-compose.yml` que defina un servicio n8n con volumen persistente — ver el bloque de código a continuación.',
