            a: 'No necesariamente. Depende de tus apps y activadores. Comprueba para cada flujo que exista un nodo de n8n o una API. Puedes dejar en Zapier los difíciles de reconstruir; el plan gratuito indicaba 100 tareas al mes el 28 de noviembre de 2026, sin webhooks.',
